// Runnable demo with package-private top-level helper classes (NOT static inner).
package com.bank.settle;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class VarDemo {
    private static final Logger log = Logger.getLogger(VarDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // GOOD var: type is obvious from the constructor. No noise, strict typing.
        var rajeshBalance = new BigDecimal("1000000.00");   // inferred: BigDecimal
        var rate = new BigDecimal("0.06");                   // inferred: BigDecimal

        // GOOD var: long duplicated generic collapsed to one line.
        var transactions = new ArrayList<Transaction>();     // inferred: ArrayList<Transaction>
        transactions.add(new Transaction("SAV2001", new BigDecimal("50000.00")));
        transactions.add(new Transaction("SAV2001", new BigDecimal("25000.00")));
        transactions.add(new Transaction("CUR3001", new BigDecimal("10000.00")));

        // GOOD var: factory method whose name makes the type clear.
        var calculator = new InterestCalculator();

        // var is STRICT: the next line would NOT compile:
        // rajeshBalance = "a lot of money";   // ERROR: rajeshBalance is a BigDecimal

        // Limitation examples (shown as comments — they do not compile):
        // var nothing;            // ERROR: needs an initializer
        // var empty = null;       // ERROR: null has no definite type
        // var arr = {1, 2, 3};    // ERROR: array initializer needs a type
        // var fn  = x -> x + 1;   // ERROR: lambda needs a target type

        BigDecimal interest = calculator.computeInterest(rajeshBalance, rate);
        log.info(() -> "Rajesh interest on Rs." + rajeshBalance + " = Rs." + interest);

        // GOOD var in enhanced for-loop and with grouping Map.
        var grouped = new HashMap<String, BigDecimal>();     // inferred: HashMap<String, BigDecimal>
        for (var txn : transactions) {                       // inferred: Transaction
            grouped.merge(txn.getAccountId(), txn.getAmount(), BigDecimal::add);
        }
        grouped.forEach((acct, sum) -> log.info(() -> "Account " + acct + " total Rs." + sum));
    }
}

// ─── Would be in model/Transaction.java in a real project ───
class Transaction {
    private final String accountId;
    private final BigDecimal amount;

    Transaction(String accountId, BigDecimal amount) {
        this.accountId = accountId;
        this.amount = amount;
    }
    String getAccountId() { return accountId; }
    BigDecimal getAmount() { return amount; }
}

// ─── Would be in service/InterestCalculator.java in a real project ───
class InterestCalculator {
    BigDecimal computeInterest(BigDecimal principal, BigDecimal rate) {
        // Money math is always BigDecimal, never float/double.
        return principal.multiply(rate).setScale(2, java.math.RoundingMode.HALF_UP);
    }
}
